import { useState } from "react";
import { useQuery, getProducts, getCoupon, checkout } from "wasp/client/operations";
import "./Main.css";

export function MainPage() {
  const { data: products, isLoading, error: productsError } = useQuery(getProducts);

  const [cart, setCart] = useState<Array<{
    productId: number;
    name: string;
    price: number;
    quantity: number;
  }>>([]);

  const [couponCode, setCouponCode] = useState("");
  const [appliedCoupon, setAppliedCoupon] = useState<any>(null);
  const [couponMessage, setCouponMessage] = useState<{ text: string; isError: boolean } | null>(null);
  const [checkoutMessage, setCheckoutMessage] = useState<{ text: string; isError: boolean } | null>(null);

  const addToCart = (product: any) => {
    setCart((prevCart) => {
      const existing = prevCart.find((item) => item.productId === product.id);
      if (existing) {
        return prevCart.map((item) =>
          item.productId === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      } else {
        return [
          ...prevCart,
          {
            productId: product.id,
            name: product.name,
            price: product.price,
            quantity: 1,
          },
        ];
      }
    });
  };

  const updateQuantity = (productId: number, delta: number) => {
    setCart((prevCart) => {
      return prevCart
        .map((item) => {
          if (item.productId === productId) {
            const newQty = item.quantity + delta;
            return { ...item, quantity: newQty };
          }
          return item;
        })
        .filter((item) => item.quantity > 0);
    });
  };

  const removeFromCart = (productId: number) => {
    setCart((prevCart) => prevCart.filter((item) => item.productId !== productId));
  };

  const handleApplyCoupon = async () => {
    setCouponMessage(null);
    if (!couponCode.trim()) {
      setCouponMessage({ text: "Please enter a coupon code", isError: true });
      return;
    }
    try {
      const coupon = await getCoupon({ code: couponCode });
      setAppliedCoupon(coupon);
      setCouponMessage({ text: `Coupon "${coupon.code}" applied successfully!`, isError: false });
    } catch (err: any) {
      setAppliedCoupon(null);
      setCouponMessage({ text: err.message || "Invalid coupon code", isError: true });
    }
  };

  const handlePlaceOrder = async () => {
    setCheckoutMessage(null);
    if (cart.length === 0) {
      setCheckoutMessage({ text: "Your cart is empty", isError: true });
      return;
    }
    try {
      const result = await checkout({
        items: cart.map((item) => ({
          productId: item.productId,
          quantity: item.quantity,
        })),
        couponCode: appliedCoupon ? appliedCoupon.code : undefined,
      });
      setCheckoutMessage({
        text: `Order placed successfully! Order ID: ${result.orderId}`,
        isError: false,
      });
      // Clear cart and coupon state on success
      setCart([]);
      setAppliedCoupon(null);
      setCouponCode("");
      setCouponMessage(null);
    } catch (err: any) {
      setCheckoutMessage({
        text: err.message || "An error occurred during checkout",
        isError: true,
      });
    }
  };

  // Calculate prices
  const subtotal = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
  let discount = 0;
  if (appliedCoupon) {
    if (appliedCoupon.type === "percentage") {
      discount = subtotal * (appliedCoupon.value / 100);
    } else if (appliedCoupon.type === "flat") {
      discount = appliedCoupon.value;
    }
  }
  discount = Math.min(subtotal, discount);
  const grandTotal = subtotal - discount;

  return (
    <div className="app-container">
      <header className="header">
        <h1>Wasp E-Commerce</h1>
        <p>Checkout with Inventory Tracking and Concurrency</p>
      </header>

      <main className="main-content">
        <section className="catalog-section">
          <h2>Product Catalog</h2>
          {isLoading && <p>Loading products...</p>}
          {productsError && <p className="error-message">Error loading products: {productsError.message}</p>}
          {products && products.length === 0 && <p>No products available.</p>}

          <div className="product-grid">
            {products && products.map((product) => (
              <div key={product.id} className="product-card">
                <h3>{product.name}</h3>
                <p className="product-price">${product.price.toFixed(2)}</p>
                <p className="product-inventory">
                  Available: <span className="inventory-count">{product.inventory}</span>
                </p>
                <button
                  onClick={() => addToCart(product)}
                  disabled={product.inventory <= 0}
                  className="add-to-cart-btn"
                >
                  {product.inventory > 0 ? "Add to Cart" : "Out of Stock"}
                </button>
              </div>
            ))}
          </div>
        </section>

        <section className="cart-section">
          <h2>Shopping Cart</h2>
          {cart.length === 0 ? (
            <p className="empty-cart-msg">Your cart is empty.</p>
          ) : (
            <div className="cart-container">
              <ul className="cart-items-list">
                {cart.map((item) => (
                  <li key={item.productId} className="cart-item">
                    <div className="cart-item-info">
                      <span className="cart-item-name">{item.name}</span>
                      <span className="cart-item-price">${item.price.toFixed(2)} each</span>
                    </div>
                    <div className="cart-item-actions">
                      <button onClick={() => updateQuantity(item.productId, -1)}>-</button>
                      <span className="cart-item-quantity">{item.quantity}</span>
                      <button onClick={() => updateQuantity(item.productId, 1)}>+</button>
                      <button onClick={() => removeFromCart(item.productId)} className="remove-btn">Remove</button>
                    </div>
                  </li>
                ))}
              </ul>

              <div className="coupon-container">
                <input
                  id="coupon-input"
                  type="text"
                  placeholder="Enter Coupon Code"
                  value={couponCode}
                  onChange={(e) => setCouponCode(e.target.value)}
                  className="coupon-input-field"
                />
                <button
                  id="apply-coupon-btn"
                  onClick={handleApplyCoupon}
                  className="apply-coupon-btn"
                >
                  Apply Coupon
                </button>
              </div>

              {couponMessage && (
                <p className={`coupon-msg ${couponMessage.isError ? "error" : "success"}`}>
                  {couponMessage.text}
                </p>
              )}

              <div className="cart-summary">
                <div className="summary-row">
                  <span>Subtotal:</span>
                  <span>${subtotal.toFixed(2)}</span>
                </div>
                <div className="summary-row">
                  <span>Discount:</span>
                  <span>-${discount.toFixed(2)}</span>
                </div>
                <div className="summary-row grand-total">
                  <span>Grand Total:</span>
                  <span>${grandTotal.toFixed(2)}</span>
                </div>
              </div>

              <button
                id="checkout-btn"
                onClick={handlePlaceOrder}
                className="checkout-btn"
              >
                Place Order
              </button>

              {checkoutMessage && (
                <div className={`checkout-msg ${checkoutMessage.isError ? "error" : "success"}`}>
                  {checkoutMessage.text}
                </div>
              )}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: #f7fafc;
  color: #2d3748;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
  width: 100%;
}

.header {
  text-align: center;
  margin-bottom: 3rem;
  border-bottom: 2px solid #e2e8f0;
  padding-bottom: 1.5rem;
}

.header h1 {
  font-size: 2.5rem;
  color: #1a202c;
  margin-bottom: 0.5rem;
}

.header p {
  font-size: 1.1rem;
  color: #718096;
}

.main-content {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 2.5rem;
}

@media (max-width: 768px) {
  .main-content {
    grid-template-columns: 1fr;
  }
}

h2 {
  font-size: 1.5rem;
  color: #2d3748;
  margin-bottom: 1.5rem;
  border-bottom: 1px solid #edf2f7;
  padding-bottom: 0.5rem;
}

/* Catalog Section */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: white;
  border-radius: 8px;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.product-card h3 {
  font-size: 1.25rem;
  color: #1a202c;
  margin-bottom: 0.5rem;
}

.product-price {
  font-size: 1.5rem;
  font-weight: bold;
  color: #2b6cb0;
  margin-bottom: 0.5rem;
}

.product-inventory {
  font-size: 0.95rem;
  color: #4a5568;
  margin-bottom: 1.5rem;
}

.inventory-count {
  font-weight: bold;
  color: #2d3748;
}

.add-to-cart-btn {
  width: 100%;
  background-color: #3182ce;
  color: white;
  border: none;
  padding: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.add-to-cart-btn:hover:not(:disabled) {
  background-color: #2b6cb0;
}

.add-to-cart-btn:disabled {
  background-color: #cbd5e0;
  cursor: not-allowed;
}

/* Cart Section */
.cart-section {
  background: white;
  border-radius: 8px;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
  padding: 2rem;
  height: fit-content;
}

.empty-cart-msg {
  color: #718096;
  text-align: center;
  padding: 2rem 0;
  font-style: italic;
}

.cart-items-list {
  list-style: none;
  margin-bottom: 1.5rem;
}

.cart-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 0;
  border-bottom: 1px solid #edf2f7;
}

.cart-item-info {
  display: flex;
  flex-direction: column;
}

.cart-item-name {
  font-weight: 600;
  color: #2d3748;
}

.cart-item-price {
  font-size: 0.9rem;
  color: #718096;
}

.cart-item-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.cart-item-actions button {
  background-color: #edf2f7;
  border: none;
  width: 28px;
  height: 28px;
  border-radius: 4px;
  font-weight: bold;
  cursor: pointer;
  transition: background-color 0.1s;
}

.cart-item-actions button:hover {
  background-color: #e2e8f0;
}

.cart-item-actions .remove-btn {
  background-color: #fff5f5;
  color: #e53e3e;
  width: auto;
  height: auto;
  padding: 0.35rem 0.75rem;
  font-size: 0.85rem;
  font-weight: 500;
}

.cart-item-actions .remove-btn:hover {
  background-color: #fed7d7;
}

.cart-item-quantity {
  font-weight: 600;
  width: 24px;
  text-align: center;
}

/* Coupon section */
.coupon-container {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.coupon-input-field {
  flex: 1;
  padding: 0.6rem 0.75rem;
  border: 1px solid #cbd5e0;
  border-radius: 6px;
  font-size: 0.95rem;
  outline: none;
}

.coupon-input-field:focus {
  border-color: #3182ce;
  box-shadow: 0 0 0 3px rgba(66, 153, 225, 0.15);
}

.apply-coupon-btn {
  background-color: #4a5568;
  color: white;
  border: none;
  padding: 0.6rem 1rem;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s;
}

.apply-coupon-btn:hover {
  background-color: #2d3748;
}

.coupon-msg {
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
  font-weight: 500;
}

.coupon-msg.success {
  color: #38a169;
}

.coupon-msg.error {
  color: #e53e3e;
}

/* Summary and Checkout */
.cart-summary {
  background-color: #f7fafc;
  padding: 1.25rem;
  border-radius: 6px;
  margin-bottom: 1.5rem;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.75rem;
  color: #4a5568;
}

.summary-row.grand-total {
  margin-top: 0.75rem;
  padding-top: 0.75rem;
  border-top: 2px dashed #cbd5e0;
  font-size: 1.25rem;
  font-weight: bold;
  color: #1a202c;
}

.checkout-btn {
  width: 100%;
  background-color: #38a169;
  color: white;
  border: none;
  padding: 0.9rem;
  font-size: 1.1rem;
  font-weight: 700;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1);
}

.checkout-btn:hover {
  background-color: #2f855a;
}

.checkout-msg {
  margin-top: 1.5rem;
  padding: 1rem;
  border-radius: 6px;
  font-weight: 500;
  text-align: center;
}

.checkout-msg.success {
  background-color: #f0fff4;
  border: 1px solid #c6f6d5;
  color: #22543d;
}

.checkout-msg.error {
  background-color: #fff5f5;
  border: 1px solid #fed7d7;
  color: #742a2a;
}

.error-message {
  color: #e53e3e;
  margin-bottom: 1rem;
  font-weight: 500;
}

import { PrismaClient } from '@prisma/client';
import { checkout } from './actions';

const prisma = new PrismaClient();

async function runTest() {
  console.log("Starting concurrency test...");

  // Reset database state first
  await prisma.orderItem.deleteMany({});
  await prisma.order.deleteMany({});
  await prisma.product.deleteMany({});
  await prisma.coupon.deleteMany({});

  // Insert a product with inventory 1
  const keyboard = await prisma.product.create({
    data: {
      name: "Ergonomic Mechanical Keyboard",
      price: 150.00,
      inventory: 1,
    },
  });

  console.log(`Created product: ${keyboard.name} with inventory: ${keyboard.inventory}`);

  const items = [{ productId: keyboard.id, quantity: 1 }];

  // Fire two concurrent checkout requests
  console.log("Firing 2 concurrent checkout requests...");
  const results = await Promise.allSettled([
    checkout({ items }, { entities: { Product: prisma.product, Coupon: prisma.coupon, Order: prisma.order, OrderItem: prisma.orderItem } }),
    checkout({ items }, { entities: { Product: prisma.product, Coupon: prisma.coupon, Order: prisma.order, OrderItem: prisma.orderItem } }),
  ]);

  let successCount = 0;
  let failureCount = 0;
  let failureReason = "";

  results.forEach((res, i) => {
    if (res.status === 'fulfilled') {
      successCount++;
      console.log(`Request ${i + 1} succeeded:`, res.value);
    } else {
      failureCount++;
      failureReason = res.reason.message;
      console.log(`Request ${i + 1} failed with error:`, res.reason.message);
    }
  });

  // Verify inventory is 0
  const updatedKeyboard = await prisma.product.findUnique({
    where: { id: keyboard.id },
  });
  console.log(`Updated inventory: ${updatedKeyboard?.inventory}`);

  // Assertions
  if (successCount === 1 && failureCount === 1 && updatedKeyboard?.inventory === 0) {
    console.log("SUCCESS: Concurrency test passed perfectly!");
    console.log(`Failed request reason contains "Insufficient inventory": ${failureReason.includes("Insufficient inventory") || failureReason.includes("Out of stock")}`);
  } else {
    console.error("FAILURE: Concurrency test failed!");
    process.exit(1);
  }

  await prisma.$disconnect();
}

runTest().catch((err) => {
  console.error("Test error:", err);
  process.exit(1);
});
